import{_ as e,o as d,c as t,a8 as c}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.35 正则高级用法通关","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.35-regex-advanced.md","filePath":"comics/EP.35-regex-advanced.md","lastUpdated":1792817913000}'),a={name:"comics/EP.35-regex-advanced.md"};function r(l,o,n,i,s,g){return d(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="ep-35-正则高级用法通关" tabindex="-1">EP.35 正则高级用法通关 <a class="header-anchor" href="#ep-35-正则高级用法通关" aria-label="Permalink to &quot;EP.35 正则高级用法通关&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../01-javascript-advanced">01-javascript-advanced.md</a> 1.15 节 · 示例：<code>examples/01-37-regex-advanced.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：像素酱用 <code>/&lt;.+&gt;/</code> 提取标签，结果整串被贪婪吞光；换成惰性 <code>/&lt;.+?&gt;/</code> 才停在第一个 <code>&gt;</code>。贪婪是&quot;先吃满再回吐&quot;，惰性是&quot;满足即停&quot;。</li><li><strong>第 2 格</strong>：码叔拆出分组三兄弟：<code>(x)</code> 捕获存值占下标、<code>(?:x)</code> 只分组不存、<code>(?&lt;n&gt;x)</code> 命名挂 <code>groups</code>；再配 <code>\\1</code>/<code>\\k&lt;n&gt;</code> 反向引用与 <code>$1</code>/<code>$&lt;n&gt;</code> 重排文本。</li><li><strong>第 3 格</strong>：标签君实测四种零宽断言 <code>?= ?! ?&lt;= ?&lt;!</code>——只看位置不吃字符，千分位与密码强度校验都是位置组合拳。</li><li><strong>第 4 格</strong>：码叔结案：贪婪遇嵌套跨标签吞并、嵌套量词指数回溯 ReDoS、负向先行回溯截尾、ES2025 重复命名组需特性检测——坑全在回溯上。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-贪婪与惰性-同一个量词-两种策略" tabindex="-1">第 1 格 · 贪婪与惰性：同一个量词，两种策略 <a class="header-anchor" href="#第-1-格-·-贪婪与惰性-同一个量词-两种策略" aria-label="Permalink to &quot;第 1 格 · 贪婪与惰性：同一个量词，两种策略&quot;">​</a></h3><p>量词 <code>* + ? {m,n}</code> 默认<strong>贪婪</strong>：先尽量多吃，匹配不下去再逐字符回吐（回溯）；加 <code>?</code> 变<strong>惰性</strong>：刚好满足就停。<code>&#39;&lt;div&gt;&lt;span&gt;hi&lt;/span&gt;&lt;/div&gt;&#39;.match(/&lt;.+&gt;/)</code> 从 <code>&lt;</code> 一路吃到整串最后一个 <code>&gt;</code>，返回整串；<code>/&lt;.+?&gt;/</code> 见到第一个 <code>&gt;</code> 就停，返回 <code>[&#39;&lt;div&gt;&#39;]</code>。</p><p><strong>关键认知</strong>：贪婪的代价是回溯。嵌套量词如 <code>(a+)+b</code> 遇到 <code>&quot;aaa...c&quot;</code> 会指数级回溯（ReDoS），生产环境要么改写模式，要么限制输入长度。</p><h3 id="第-2-格-·-分组三兄弟与反向引用" tabindex="-1">第 2 格 · 分组三兄弟与反向引用 <a class="header-anchor" href="#第-2-格-·-分组三兄弟与反向引用" aria-label="Permalink to &quot;第 2 格 · 分组三兄弟与反向引用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>语法</th><th>名字</th><th>作用</th></tr></thead><tbody><tr><td><code>(x)</code></td><td>捕获组</td><td>存子表达式结果，按 <code>match</code> 下标取（第 0 项是整体）</td></tr><tr><td><code>(?:x)</code></td><td>非捕获组</td><td>只分组不保存，不占下标，语义更清晰</td></tr><tr><td><code>(?&lt;n&gt;x)</code></td><td>命名组</td><td>结果挂在 <code>m.groups.n</code>，可读性远好于魔法下标</td></tr></tbody></table><ul><li><strong>反向引用 <code>\\1</code></strong>：引用第 1 组<strong>实际匹配到的文本</strong>，不是把分组里的模式再匹配一遍——<code>(\\w+)-\\1</code> 匹配 <code>ab-ab</code>，<code>&lt;(\\w)&gt;.*&lt;/\\1&gt;</code> 要求开合标签名一致；</li><li><strong>replace 侧 <code>$1</code> / <code>$&lt;name&gt;</code></strong>：引用捕获组重排文本，如 <code>&#39;2026-10-18&#39;.replace(/(\\d{4})-(\\d{2})-(\\d{2})/, &#39;$3/$2/$1&#39;)</code>；</li><li><strong><code>matchAll</code> + <code>/g</code></strong>：遍历全部匹配，每项都带完整分组信息，是 <code>exec</code> 循环的现代替代品。</li></ul><h3 id="第-3-格-·-四种零宽断言" tabindex="-1">第 3 格 · 四种零宽断言 <a class="header-anchor" href="#第-3-格-·-四种零宽断言" aria-label="Permalink to &quot;第 3 格 · 四种零宽断言&quot;">​</a></h3><p>断言只&quot;看一眼&quot;位置，不&quot;吃&quot;任何字符：</p><table tabindex="0"><thead><tr><th>断言</th><th>方向</th><th>语义</th></tr></thead><tbody><tr><td><code>(?=X)</code></td><td>正向先行</td><td>右侧必须是 X</td></tr><tr><td><code>(?!X)</code></td><td>负向先行</td><td>右侧不能是 X</td></tr><tr><td><code>(?&lt;=X)</code></td><td>正向后行</td><td>左侧必须是 X</td></tr><tr><td><code>(?&lt;!X)</code></td><td>负向后行</td><td>左侧不能是 X</td></tr></tbody></table><p>组合拳两例：千分位 <code>/\\B(?=(\\d{3})+(?!\\d))/g</code>（非单词边界 + 右侧是完整 3 位组）；密码强度 <code>/^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?!.*\\s)\\S{8,}$/</code>——每个 <code>(?=...)</code> 都从同一起点检查，等价于&quot;同时满足&quot;的多道关卡。</p><h3 id="第-4-格-·-高频易错点" tabindex="-1">第 4 格 · 高频易错点 <a class="header-anchor" href="#第-4-格-·-高频易错点" aria-label="Permalink to &quot;第 4 格 · 高频易错点&quot;">​</a></h3><ol><li><strong>负向先行会&quot;截尾&quot;</strong>：<code>/\\d+(?!元)/g</code> 匹配 <code>&#39;100元&#39;</code>，<code>100</code> 想躲开元，回溯退到 <code>10</code> 就满足了——所以输出 <code>[&#39;10&#39;, ...]</code>。想要&quot;完整数字后面不是元&quot;要换思路（如 <code>\\d+(?![元])</code> 配合边界或改用后行断言组合）；</li><li><strong>贪婪 + 嵌套结构会跨标签吞并</strong>：解析 HTML 请用 DOM API，正则只做行内简单切分；</li><li><strong>JS 后行断言支持变长</strong>：<code>(?&lt;=¥|RMB)</code> 这种多长度分支合法（多数语言只支持定长）。</li></ol><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../01-javascript-advanced#_1-19-本章避坑清单">《1.19 本章避坑清单》</a></p></blockquote><ol><li><strong>贪婪遇嵌套跨标签吞并</strong>：<code>/&lt;.+&gt;/</code> 会从第一个 <code>&lt;</code> 吃到最后一个 <code>&gt;</code>，切 HTML 必须用 DOM API；</li><li><strong>嵌套量词指数回溯（ReDoS）</strong>：<code>(a+)+b</code> 类模式遇不匹配长串会卡死，生产环境限制长度或改写模式；</li><li><strong>负向先行回溯截尾</strong>：<code>\\d+(?!元)</code> 会把 <code>100</code> 截成 <code>10</code> 来满足条件，结果集与直觉相反，需理解回溯机制；</li><li><strong><code>\\1</code> 误当&quot;再匹配一遍模式&quot;</strong>：它引用的是第 1 组实际捕获的文本，不是模式本身；</li><li><strong>ES2025 重复命名捕获组</strong>：同分支复用组名是新语法，实测 Node v24 仍抛 <code>Duplicate capture group name</code>，必须特性检测后降级（用不同组名）。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>为什么 <code>/&lt;.+&gt;/</code> 会匹配整串 <code>&#39;&lt;div&gt;&lt;span&gt;hi&lt;/span&gt;&lt;/div&gt;&#39;</code>？怎么改？</strong>——量词 <code>+</code> 默认贪婪：从第一个 <code>&lt;</code> 起，<code>.</code> 一路吃到整串最后一个 <code>&gt;</code> 才满足；中途每个 <code>&gt;</code> 它都&quot;还能继续吃&quot;，所以不停。改成惰性 <code>/&lt;.+?&gt;/</code>（量词后加 <code>?</code>），刚好满足第一个 <code>&gt;</code> 就停，返回 <code>[&#39;&lt;div&gt;&#39;]</code>。</li><li><strong><code>/\\d+(?!元)/g</code> 匹配 <code>&#39;100元&#39;</code> 得到 <code>10</code> 而不是空，为什么？</strong>——负向先行只要求&quot;当前位置右侧不是元&quot;。<code>100</code> 整体后面是元不满足，但引擎会回溯：退到 <code>10</code> 时右侧是 <code>0</code>，满足条件，于是捕获 <code>10</code>。断言约束的是&quot;匹配结束的位置&quot;，不是&quot;整个数字&quot;。</li><li><strong>千分位正则 <code>/\\B(?=(\\d{3})+(?!\\d))/g</code> 是怎么工作的？</strong>——<code>\\B</code> 选在数字内部（非单词边界）的位置；<code>(?=(\\d{3})+(?!\\d))</code> 要求从该位置到数字末尾恰好由若干完整 3 位组构成（<code>(?!\\d)</code> 防止 3 位组后面还拖着数字，保证从右往左每 3 位一组）；两个零宽条件叠加，在每个合法插入点插入 <code>,</code>，<code>&#39;12345678&#39;</code> 即变 <code>&#39;12,345,678&#39;</code>。</li></ol>',22)])])}const q=e(a,[["render",r]]);export{u as __pageData,q as default};
